with client.messages.stream(
 model="claude-3-7-sonnet-20250219",
 max_tokens=2048,
 tools=MY_TOOLS,
 messages=[{"role": "user", "content": "Analyze Q3 revenues"}]
) as stream:
 for event in stream:
 if event.type == "text":
 yield f"data: {event.text}\n\n"
 elif event.type == "input_json":
 yield f"data: [TOOL_DELTA] {event.partial_json}\n\n"
